const STUDY_QUESTIONS=[{id:101,skill:1,section:"1A",bullet:"copilot-privacy",topic:"Copilot Privacy & Data Handling",question:"A colleague asks whether Microsoft uses your company's prompts and responses to train the large language model behind Copilot. What is the correct answer?",options:["Yes, anonymized prompts are added to the training set each quarter","Only prompts flagged as 'helpful' are used for training","No — Microsoft does not use customer prompts or responses to train foundation models","Prompts are used for training only if the tenant admin opts in"],correct:2,explanation:"Microsoft explicitly states that it does not use customer prompts, responses, or organizational data to train its foundation models. Data stays within the Microsoft 365 trust boundary.",source:{title:"Microsoft 365 Copilot as your workflow companion",url:"https://learn.microsoft.com/en-us/training/modules/what-generative-ai/4-copilot-workflow-companion",video:{title:"Episode 1: What is generative AI?",url:"https://www.youtube.com/watch?v=bIqV5jilJKk"}}},{id:102,skill:1,section:"1A",bullet:"copilot-privacy",topic:"Copilot Privacy & Permissions",question:"Your team stores confidential HR files in a SharePoint library with restricted permissions. A manager outside that group asks Copilot to summarize those files. What happens?",options:["Copilot returns the summary but marks it 'Confidential'","Copilot cannot surface the content because it respects existing Microsoft 365 permissions","Copilot returns a partial summary with sensitive fields redacted","Copilot asks the manager to request access, then surfaces the content"],correct:1,explanation:"Copilot inherits the same permission model as Microsoft 365. If a user lacks access to a document, Copilot will not surface or summarize its contents.",source:{title:"Microsoft 365 Copilot as your workflow companion",url:"https://learn.microsoft.com/en-us/training/modules/what-generative-ai/4-copilot-workflow-companion",video:{title:"Episode 1: What is generative AI?",url:"https://www.youtube.com/watch?v=bIqV5jilJKk"}}},{id:103,skill:1,section:"1A",bullet:"copilot-privacy",topic:"Copilot Data Encryption",question:"Which statement accurately describes how data is protected while traveling between the user and the Copilot service?",options:["Data is compressed but not encrypted to reduce latency","Data is encrypted in transit and at rest, and never leaves the Microsoft 365 trust boundary","Data is encrypted only when the user enables Advanced Data Protection","Encryption applies only to files, not to the prompt text itself"],correct:1,explanation:"All data exchanged with Copilot is encrypted both in transit and at rest. Prompts, responses, and organizational data remain within the Microsoft 365 trust boundary.",source:{title:"Microsoft 365 Copilot as your workflow companion",url:"https://learn.microsoft.com/en-us/training/modules/what-generative-ai/4-copilot-workflow-companion",video:{title:"Episode 1: What is generative AI?",url:"https://www.youtube.com/watch?v=bIqV5jilJKk"}}},{id:104,skill:1,section:"1A",bullet:"context-affects-responses",topic:"Grounding & Microsoft Graph",question:"What is the primary role of Microsoft Graph in the Copilot data-flow pipeline?",options:["It hosts the large language model used by Copilot","It provides grounding by connecting the LLM to organizational data such as emails, files, and calendar events","It stores the user's conversation history for future sessions","It translates prompts into multiple languages before sending them to the LLM"],correct:1,explanation:"Microsoft Graph grounds Copilot responses in organizational context. The data flow is Prompt → Graph (pre-processing) → LLM → Graph (post-processing) → Response, ensuring answers are relevant and accurate.",source:{title:"What is Copilot Chat?",url:"https://learn.microsoft.com/en-us/training/modules/employ-copilot-assistant/2-what-is-copilot-chat",video:{title:"Episode 2: Copilot Chat as your AI assistant",url:"https://www.youtube.com/watch?v=Nc0jM8lh9II"}}},{id:105,skill:1,section:"1A",bullet:"context-affects-responses",topic:"Work Mode vs Web Mode",question:"You need to compare your company's Q3 revenue (stored in SharePoint) with a publicly available industry benchmark. Which approach in Copilot Chat is most effective?",options:["Use Web mode — it can access both internal and external data","Use Work mode for the internal data, then switch to Web mode for the public benchmark","Use Web mode and paste the Q3 numbers manually into the prompt","Use Work mode — it automatically searches the web when needed"],correct:1,explanation:"Work mode accesses organizational data via Microsoft Graph; Web mode searches the public internet. To combine both, you use each mode for its respective data source.",source:{title:"What is Copilot Chat?",url:"https://learn.microsoft.com/en-us/training/modules/employ-copilot-assistant/2-what-is-copilot-chat",video:{title:"Episode 2: Copilot Chat as your AI assistant",url:"https://www.youtube.com/watch?v=Nc0jM8lh9II"}}},{id:106,skill:1,section:"1A",bullet:"context-affects-responses",topic:"Context from the Active App",question:"You open Copilot inside Excel while a sales spreadsheet is active. How does this affect Copilot's behavior compared to opening Copilot Chat from the browser?",options:["There is no difference — Copilot always uses the same context","Copilot in Excel automatically uses the active workbook as context, while Copilot Chat requires you to reference files manually","Copilot Chat has more context because it can access all apps simultaneously","Copilot in Excel only answers formula questions; all other topics require Copilot Chat"],correct:1,explanation:"When Copilot is launched from within an app, it automatically uses the active document as context. In Copilot Chat, you must explicitly reference files using the / command.",source:{title:"What is Copilot Chat?",url:"https://learn.microsoft.com/en-us/training/modules/employ-copilot-assistant/2-what-is-copilot-chat",video:{title:"Episode 2: Copilot Chat as your AI assistant",url:"https://www.youtube.com/watch?v=Nc0jM8lh9II"}}},{id:107,skill:1,section:"1A",bullet:"context-affects-responses",topic:"Grounding & Post-Processing",question:"After the LLM generates a response, Copilot sends it back through Microsoft Graph for post-processing. What is the main purpose of this step?",options:["To translate the response into the user's preferred language","To verify accuracy, add citations, and reduce fabrications","To compress the response for faster delivery","To log the response for compliance auditing"],correct:1,explanation:"Post-processing through Microsoft Graph verifies accuracy, adds citations to source documents, and helps reduce fabrications before the response reaches the user.",source:{title:"What is Copilot Chat?",url:"https://learn.microsoft.com/en-us/training/modules/employ-copilot-assistant/2-what-is-copilot-chat",video:{title:"Episode 2: Copilot Chat as your AI assistant",url:"https://www.youtube.com/watch?v=Nc0jM8lh9II"}}},{id:108,skill:1,section:"1A",bullet:"chat-vs-agent",topic:"Chat vs Agent Experience",question:"What is a key difference between a standard Copilot Chat conversation and an agent experience?",options:["Chat requires a Microsoft 365 license; agents do not","Agents are pre-configured with specific instructions, knowledge sources, and capabilities tailored to a task","Chat can access organizational data; agents cannot","Agents always require developer tools like Visual Studio to build"],correct:1,explanation:"Agents extend the Copilot experience by adding custom instructions, curated knowledge sources, and specific capabilities, making them task-focused rather than general-purpose.",source:{title:"Copilot agents defined",url:"https://learn.microsoft.com/en-us/training/modules/employ-copilot-assistant/4a-copilot-agents-defined",video:{title:"Episode 2: Copilot Chat as your AI assistant",url:"https://www.youtube.com/watch?v=Nc0jM8lh9II"}}},{id:109,skill:1,section:"1A",bullet:"chat-vs-agent",topic:"Chat vs Agent Experience",question:"A user wants quick answers to ad-hoc questions about their email and calendar. Should they use Copilot Chat or create an agent?",options:["Create an agent because it provides better answers","Use Copilot Chat — it is designed for general, ad-hoc questions across M365 data","Use an agent from the Agent Store for calendar tasks","Neither — they should use Microsoft Search instead"],correct:1,explanation:"Copilot Chat is ideal for general, ad-hoc queries across Microsoft 365 data. Agents are better when you need a repeatable, task-specific experience with curated knowledge.",source:{title:"Copilot agents defined",url:"https://learn.microsoft.com/en-us/training/modules/employ-copilot-assistant/4a-copilot-agents-defined",video:{title:"Episode 2: Copilot Chat as your AI assistant",url:"https://www.youtube.com/watch?v=Nc0jM8lh9II"}}},{id:110,skill:1,section:"1A",bullet:"chat-vs-agent",topic:"Chat vs Agent Experience",question:"Which scenario best illustrates when an agent is preferable to a standard Copilot Chat conversation?",options:["Asking Copilot to summarize yesterday's emails","Repeatedly onboarding new hires using the same HR policy documents and standard questions","Checking the weather forecast for a meeting location","Drafting a one-time thank-you email to a colleague"],correct:1,explanation:"Agents shine when a task is repeated frequently and benefits from pre-configured knowledge (like HR policies) and consistent instructions, making the experience reliable and efficient.",source:{title:"Copilot agents defined",url:"https://learn.microsoft.com/en-us/training/modules/employ-copilot-assistant/4a-copilot-agents-defined",video:{title:"Episode 2: Copilot Chat as your AI assistant",url:"https://www.youtube.com/watch?v=Nc0jM8lh9II"}}},{id:111,skill:1,section:"1A",bullet:"create-own-agent",topic:"Creating Your Own Agent",question:"Your department frequently answers the same customer questions using a set of approved FAQ documents. What is the best reason to create a custom Copilot agent for this?",options:["Custom agents are faster than Copilot Chat","A custom agent can be grounded in the approved FAQ documents and given instructions to answer only from those sources","Custom agents bypass Microsoft 365 permissions for faster access","Custom agents automatically translate responses into any language"],correct:1,explanation:"Creating a custom agent lets you scope it to specific knowledge sources (like FAQ documents) and add instructions that keep responses consistent and on-topic.",source:{title:"Copilot agents defined",url:"https://learn.microsoft.com/en-us/training/modules/employ-copilot-assistant/4a-copilot-agents-defined",video:{title:"Episode 2: Copilot Chat as your AI assistant",url:"https://www.youtube.com/watch?v=Nc0jM8lh9II"}}},{id:112,skill:1,section:"1A",bullet:"create-own-agent",topic:"Creating Your Own Agent",question:"What is the maximum number of knowledge sources you can add to a single Copilot agent?",options:["5","10","20","Unlimited"],correct:2,explanation:"Each Copilot agent supports a maximum of 20 knowledge sources. These can include SharePoint sites, files, and other organizational resources.",source:{title:"Copilot agents defined",url:"https://learn.microsoft.com/en-us/training/modules/employ-copilot-assistant/4a-copilot-agents-defined",video:{title:"Episode 2: Copilot Chat as your AI assistant",url:"https://www.youtube.com/watch?v=Nc0jM8lh9II"}}},{id:113,skill:1,section:"1A",bullet:"create-own-agent",topic:"Creating Your Own Agent",question:"A project manager wants to create an agent that helps team members find project status updates stored in a specific SharePoint site. Which capability makes this possible without writing code?",options:["Copilot Studio Pro developer tools","The no-code agent builder in Microsoft 365 Copilot that allows adding knowledge sources and custom instructions","Power Automate custom connectors","Azure Bot Service deployment"],correct:1,explanation:"Microsoft 365 Copilot includes a no-code agent builder where users can configure knowledge sources (like SharePoint sites), instructions, and capabilities without any development tools.",source:{title:"Copilot agents defined",url:"https://learn.microsoft.com/en-us/training/modules/employ-copilot-assistant/4a-copilot-agents-defined",video:{title:"Episode 2: Copilot Chat as your AI assistant",url:"https://www.youtube.com/watch?v=Nc0jM8lh9II"}}},{id:114,skill:1,section:"1A",bullet:"copilot-across-apps",topic:"Copilot in Word",question:"In Microsoft Word, Copilot can help you draft and rewrite content. Which of the following can Copilot in Word NOT do?",options:["Generate a first draft based on a prompt","Rewrite a selected paragraph in a different tone","Change the document's page margins and header/footer layout","Summarize a long document into key points"],correct:2,explanation:"Copilot in Word works with content — drafting, rewriting, summarizing — but it cannot change document properties like margins, headers, footers, or page layout settings.",source:{title:"Draft content using Copilot",url:"https://learn.microsoft.com/en-us/training/modules/draft-refine-business-content/2-draft-content-using-copilot",video:{title:"Episode 3: Draft and refine business content",url:"https://www.youtube.com/watch?v=O9Fx8lVdYtc"}}},{id:115,skill:1,section:"1A",bullet:"copilot-across-apps",topic:"Copilot in Excel",question:"What can Copilot in Excel do when working with a formatted table?",options:["Modify cell formatting colors and fonts","Analyze data, highlight trends, create charts, and add formula columns","Change workbook-level properties such as calculation mode","Merge cells and apply conditional formatting rules"],correct:1,explanation:"Copilot in Excel focuses on content and analysis: highlighting trends, generating charts, adding formula columns, and sorting/filtering data. It does not change formatting properties.",source:{title:"Analyze data workflows in Excel",url:"https://learn.microsoft.com/en-us/training/modules/analyze-visualize-data-copilot/2-analyze-data-workflows-excel",video:{title:"Episode 4: Analyze and visualize data",url:"https://www.youtube.com/watch?v=l8gj-ICwQRs"}}},{id:116,skill:1,section:"1A",bullet:"copilot-across-apps",topic:"Copilot in PowerPoint",question:"You ask Copilot in PowerPoint to create a presentation from a Word document. What does Copilot generate?",options:["A text-only outline that you must format manually","A full slide deck with content, layout, and speaker notes based on the document","A link to the Word document embedded in a single slide","Only the table of contents from the Word document as bullet points"],correct:1,explanation:"Copilot in PowerPoint can generate a full presentation — including slide content, layouts, and speaker notes — from a referenced Word document or prompt.",source:{title:"Draft content using Copilot",url:"https://learn.microsoft.com/en-us/training/modules/draft-refine-business-content/2-draft-content-using-copilot",video:{title:"Episode 3: Draft and refine business content",url:"https://www.youtube.com/watch?v=O9Fx8lVdYtc"}}},{id:117,skill:1,section:"1A",bullet:"copilot-across-apps",topic:"Copilot in Outlook",question:"Which task can Copilot in Outlook perform?",options:["Automatically move emails to folders based on content","Summarize a long email thread and draft a reply","Change mailbox rules and retention policies","Schedule recurring meetings without user confirmation"],correct:1,explanation:"Copilot in Outlook can summarize email threads, draft replies, and coach you on tone. It works with email content, not mailbox properties or rules.",source:{title:"Draft content using Copilot",url:"https://learn.microsoft.com/en-us/training/modules/draft-refine-business-content/2-draft-content-using-copilot",video:{title:"Episode 3: Draft and refine business content",url:"https://www.youtube.com/watch?v=O9Fx8lVdYtc"}}},{id:118,skill:1,section:"1B",bullet:"common-risks",topic:"Fabrication Risk",question:"Copilot generates a response that includes a statistic not found in any source document. This is an example of which AI risk?",options:["Prompt injection","Over-reliance","Fabrication (hallucination)","Data leakage"],correct:2,explanation:"Fabrication (also called hallucination) occurs when the AI generates content that sounds plausible but is not grounded in actual data. Always verify statistics against original sources.",source:{title:"Understand responsible AI",url:"https://learn.microsoft.com/en-us/training/modules/what-generative-ai/3-understand-responsible-ai",video:{title:"Episode 1: What is generative AI?",url:"https://www.youtube.com/watch?v=bIqV5jilJKk"}}},{id:119,skill:1,section:"1B",bullet:"common-risks",topic:"Prompt Injection",question:"A user copies text from an external website into their prompt. The pasted text contains hidden instructions telling Copilot to ignore its safety guidelines. This is an example of:",options:["Fabrication","Over-reliance","Prompt injection","Social engineering"],correct:2,explanation:"Prompt injection occurs when malicious instructions are embedded in content that gets included in a prompt, attempting to override the AI's intended behavior.",source:{title:"Understand responsible AI",url:"https://learn.microsoft.com/en-us/training/modules/what-generative-ai/3-understand-responsible-ai",video:{title:"Episode 1: What is generative AI?",url:"https://www.youtube.com/watch?v=bIqV5jilJKk"}}},{id:120,skill:1,section:"1B",bullet:"common-risks",topic:"Over-Reliance",question:"A marketing team uses Copilot to draft a press release and publishes it without any human review. Which responsible AI risk does this demonstrate?",options:["Fabrication","Prompt injection","Over-reliance on AI-generated content","Data exfiltration"],correct:2,explanation:"Over-reliance occurs when users trust AI output without verification. AI-generated content should always be reviewed by a human before publication, especially for external communications.",source:{title:"Understand responsible AI",url:"https://learn.microsoft.com/en-us/training/modules/what-generative-ai/3-understand-responsible-ai",video:{title:"Episode 1: What is generative AI?",url:"https://www.youtube.com/watch?v=bIqV5jilJKk"}}},{id:121,skill:1,section:"1B",bullet:"common-risks",topic:"Six AI Principles",question:"Microsoft's responsible AI framework includes six principles. Which of the following is NOT one of the six principles?",options:["Fairness","Inclusiveness","Profitability","Transparency"],correct:2,explanation:"The six Microsoft responsible AI principles are: Fairness, Reliability & Safety, Privacy & Security, Inclusiveness, Transparency, and Accountability. Profitability is not one of them.",source:{title:"Understand responsible AI",url:"https://learn.microsoft.com/en-us/training/modules/what-generative-ai/3-understand-responsible-ai",video:{title:"Episode 1: What is generative AI?",url:"https://www.youtube.com/watch?v=bIqV5jilJKk"}}},{id:122,skill:1,section:"1B",bullet:"verification-steps",topic:"Citation Checks",question:"Copilot provides a summary with numbered citations. What should you do to verify the response?",options:["Assume it is correct because citations are provided","Click the citations to open the source documents and confirm the information matches","Ask Copilot to verify its own answer","Forward the response to IT for validation"],correct:1,explanation:"Citations in Copilot responses are clickable links to source documents. You should open them to verify that the AI's summary accurately reflects the original content.",source:{title:"Understand responsible AI",url:"https://learn.microsoft.com/en-us/training/modules/what-generative-ai/3-understand-responsible-ai",video:{title:"Episode 1: What is generative AI?",url:"https://www.youtube.com/watch?v=bIqV5jilJKk"}}},{id:123,skill:1,section:"1B",bullet:"verification-steps",topic:"Human Review",question:"You use Copilot to draft a financial report for the board of directors. Which verification step is most important before distribution?",options:["Run the report through spell-check","Have a subject-matter expert review all figures and claims against original data sources","Ask Copilot to regenerate the report for a second opinion","Check that the formatting matches the company template"],correct:1,explanation:"For high-stakes content like financial reports, human review by a subject-matter expert is critical. They can verify figures against original data and catch any fabrications.",source:{title:"Understand responsible AI",url:"https://learn.microsoft.com/en-us/training/modules/what-generative-ai/3-understand-responsible-ai",video:{title:"Episode 1: What is generative AI?",url:"https://www.youtube.com/watch?v=bIqV5jilJKk"}}},{id:124,skill:1,section:"1B",bullet:"verification-steps",topic:"Verification Appropriate to Task",question:"For which task is a quick self-review sufficient rather than a formal expert review?",options:["A legal contract clause generated by Copilot","An internal brainstorming list of meeting agenda ideas","A patient diagnosis summary in a healthcare setting","A compliance report submitted to regulators"],correct:1,explanation:"The level of verification should match the risk. A casual brainstorming list needs only a quick self-review, while legal, medical, or regulatory content requires expert validation.",source:{title:"Understand responsible AI",url:"https://learn.microsoft.com/en-us/training/modules/what-generative-ai/3-understand-responsible-ai",video:{title:"Episode 1: What is generative AI?",url:"https://www.youtube.com/watch?v=bIqV5jilJKk"}}},{id:125,skill:1,section:"1B",bullet:"sensitive-data-risks",topic:"Sensitive Data in Prompts",question:"An employee pastes a customer's credit card number into a Copilot prompt to ask about payment processing steps. What is the primary risk?",options:["Copilot will reject the prompt entirely","The sensitive data could appear in Copilot's response or be stored in conversation history accessible to others with permissions","Credit card numbers are automatically encrypted by Copilot","There is no risk because Copilot does not store prompts"],correct:1,explanation:"Pasting sensitive data like credit card numbers into prompts risks exposing that data in responses or conversation logs. Users should avoid including PII or sensitive data in prompts.",source:{title:"Understand responsible AI",url:"https://learn.microsoft.com/en-us/training/modules/what-generative-ai/3-understand-responsible-ai",video:{title:"Episode 1: What is generative AI?",url:"https://www.youtube.com/watch?v=bIqV5jilJKk"}}},{id:126,skill:1,section:"1B",bullet:"sensitive-data-risks",topic:"Oversharing Risk",question:"An organization discovers that Copilot is surfacing confidential salary data to managers who should not see it. What is the most likely root cause?",options:["A bug in the Copilot AI model","Overly broad file permissions in SharePoint or OneDrive that give too many users access","Copilot bypasses permissions for manager-level accounts","The salary file was stored in a public Teams channel by mistake"],correct:1,explanation:"Copilot respects existing permissions. If sensitive data is surfaced to unauthorized users, the root cause is almost always overly broad permissions — not a Copilot flaw.",source:{title:"Microsoft 365 Copilot as your workflow companion",url:"https://learn.microsoft.com/en-us/training/modules/what-generative-ai/4-copilot-workflow-companion",video:{title:"Episode 1: What is generative AI?",url:"https://www.youtube.com/watch?v=bIqV5jilJKk"}}},{id:127,skill:1,section:"1B",bullet:"sensitive-data-risks",topic:"Mitigating Sensitive Data Risks",question:"Which action best mitigates the risk of Copilot surfacing sensitive data to unauthorized users?",options:["Disable Copilot for all users in the organization","Review and tighten Microsoft 365 file and site permissions using least-privilege principles","Store all sensitive data in local desktop folders instead of SharePoint","Ask users to sign a policy agreeing not to ask about sensitive topics"],correct:1,explanation:"The best mitigation is to audit and tighten permissions using least-privilege access. Since Copilot respects M365 permissions, fixing permissions fixes the exposure.",source:{title:"Microsoft 365 Copilot as your workflow companion",url:"https://learn.microsoft.com/en-us/training/modules/what-generative-ai/4-copilot-workflow-companion",video:{title:"Episode 1: What is generative AI?",url:"https://www.youtube.com/watch?v=bIqV5jilJKk"}}},{id:128,skill:1,section:"1B",bullet:"data-protection-restrictions",topic:"Sensitivity Labels",question:"A document has a 'Highly Confidential' sensitivity label applied via Microsoft Purview. How does this affect Copilot?",options:["Copilot ignores sensitivity labels and returns the content anyway","Copilot respects the label and restricts access to the content based on the label's policy","Copilot removes the label before processing the document","Sensitivity labels only affect email, not Copilot"],correct:1,explanation:"Copilot respects Microsoft Purview sensitivity labels. If a label restricts who can view or share content, Copilot enforces those restrictions in its responses.",source:{title:"Microsoft 365 Copilot as your workflow companion",url:"https://learn.microsoft.com/en-us/training/modules/what-generative-ai/4-copilot-workflow-companion",video:{title:"Episode 1: What is generative AI?",url:"https://www.youtube.com/watch?v=bIqV5jilJKk"}}},{id:129,skill:1,section:"1B",bullet:"data-protection-restrictions",topic:"DLP Policies and Copilot",question:"An organization has Data Loss Prevention (DLP) policies that block sharing of Social Security Numbers externally. How do these policies interact with Copilot?",options:["DLP policies do not apply to AI-generated content","Copilot operates within the existing compliance framework, so DLP policies continue to apply","DLP policies only trigger when content is emailed, not when generated by Copilot","Copilot has its own separate DLP engine"],correct:1,explanation:"Copilot operates within the organization's existing compliance framework. DLP policies, retention policies, and other compliance controls continue to apply to AI-generated content.",source:{title:"Microsoft 365 Copilot as your workflow companion",url:"https://learn.microsoft.com/en-us/training/modules/what-generative-ai/4-copilot-workflow-companion",video:{title:"Episode 1: What is generative AI?",url:"https://www.youtube.com/watch?v=bIqV5jilJKk"}}},{id:130,skill:1,section:"1B",bullet:"data-protection-restrictions",topic:"Licensed vs Unlicensed Access",question:"What is the difference between a licensed and an unlicensed Copilot experience?",options:["Licensed users get faster responses; unlicensed users get the same content but slower","Licensed users can access organizational data via Microsoft Graph; unlicensed users can only use web-grounded responses","There is no functional difference — licensing only affects billing","Unlicensed users can access organizational data but cannot save conversations"],correct:1,explanation:"A Microsoft 365 Copilot license enables access to organizational data through Microsoft Graph (Work mode). Without a license, users can only use web-grounded Copilot features.",source:{title:"What is Copilot Chat?",url:"https://learn.microsoft.com/en-us/training/modules/employ-copilot-assistant/2-what-is-copilot-chat",video:{title:"Episode 2: Copilot Chat as your AI assistant",url:"https://www.youtube.com/watch?v=Nc0jM8lh9II"}}},{id:131,skill:2,section:"2A",bullet:"effective-prompts",topic:"Four Prompt Components",question:"An effective Copilot prompt includes up to four components. Which set correctly lists all four?",options:["Goal, Context, Source, Expectations","Task, Input, Format, Length","Subject, Verb, Object, Tone","Question, Data, Style, Audience"],correct:0,explanation:"Microsoft recommends structuring prompts with four components: Goal (what you want), Context (background information), Source (data to reference), and Expectations (format/tone requirements).",source:{title:"Write effective prompts",url:"https://learn.microsoft.com/en-us/training/modules/employ-copilot-assistant/3-write-effective-prompts-optimize-copilot-responses",video:{title:"Episode 2: Copilot Chat as your AI assistant",url:"https://www.youtube.com/watch?v=Nc0jM8lh9II"}}},{id:132,skill:2,section:"2A",bullet:"effective-prompts",topic:"Iterative Prompting",question:"Copilot's first response to your prompt is too generic. What is the recommended approach?",options:["Start a new conversation and try a completely different prompt","Iterate — refine the prompt by adding more context, specifying sources, or clarifying expectations in a follow-up message","Report the issue to Microsoft Support","Switch to a different AI tool for better results"],correct:1,explanation:"Copilot conversations are iterative. If the first response is not specific enough, refine by adding context, referencing specific files, or specifying the desired format in follow-up prompts.",source:{title:"Write effective prompts",url:"https://learn.microsoft.com/en-us/training/modules/employ-copilot-assistant/3-write-effective-prompts-optimize-copilot-responses",video:{title:"Episode 2: Copilot Chat as your AI assistant",url:"https://www.youtube.com/watch?v=Nc0jM8lh9II"}}},{id:133,skill:2,section:"2A",bullet:"effective-prompts",topic:"Prompt Specificity",question:"Which prompt is most likely to produce a useful Copilot response?",options:["Tell me about sales","Summarize the key trends from Q3 sales data in /Q3-Sales-Report.xlsx and list the top 3 product categories by revenue in a bullet list","Give me a good analysis","What can you do with Excel?"],correct:1,explanation:"The best prompt includes a clear Goal (summarize trends), Source (specific file), Context (Q3 sales), and Expectations (bullet list, top 3). Vague prompts produce vague answers.",source:{title:"Write effective prompts",url:"https://learn.microsoft.com/en-us/training/modules/employ-copilot-assistant/3-write-effective-prompts-optimize-copilot-responses",video:{title:"Episode 2: Copilot Chat as your AI assistant",url:"https://www.youtube.com/watch?v=Nc0jM8lh9II"}}},{id:134,skill:2,section:"2A",bullet:"effective-prompts",topic:"Fairness vs Inclusiveness",question:"In Microsoft's responsible AI principles, how do fairness and inclusiveness differ?",options:["They are the same principle with different names","Fairness means AI should not discriminate against groups; inclusiveness means AI should be accessible and usable by people of all abilities","Fairness applies to data; inclusiveness applies to user interface design","Inclusiveness is about language translation; fairness is about equal pricing"],correct:1,explanation:"Fairness ensures AI does not produce biased or discriminatory outcomes. Inclusiveness ensures AI is designed to be accessible to people of all abilities and backgrounds. They are related but distinct.",source:{title:"Understand responsible AI",url:"https://learn.microsoft.com/en-us/training/modules/what-generative-ai/3-understand-responsible-ai",video:{title:"Episode 1: What is generative AI?",url:"https://www.youtube.com/watch?v=bIqV5jilJKk"}}},{id:135,skill:2,section:"2A",bullet:"reference-resources",topic:"Referencing Files with /",question:"In Copilot Chat, what does typing the / character in your prompt allow you to do?",options:["Insert a line break in the prompt","Reference a specific file from OneDrive or SharePoint to include as context","Switch between Work and Web mode","Access Copilot keyboard shortcuts"],correct:1,explanation:"The / command in Copilot Chat lets you reference specific files from OneDrive or SharePoint, giving Copilot targeted context for your prompt.",source:{title:"Write effective prompts",url:"https://learn.microsoft.com/en-us/training/modules/employ-copilot-assistant/3-write-effective-prompts-optimize-copilot-responses",video:{title:"Episode 2: Copilot Chat as your AI assistant",url:"https://www.youtube.com/watch?v=Nc0jM8lh9II"}}},{id:136,skill:2,section:"2A",bullet:"reference-resources",topic:"Referencing People with @",question:"What happens when you type @ followed by a colleague's name in a Copilot prompt?",options:["It sends a notification to that colleague","It references that person's context — such as their recent emails, chats, or shared files — in the query","It starts a video call with that person","It grants that person access to your Copilot conversation"],correct:1,explanation:"Using @ followed by a person's name tells Copilot to include context related to that person, such as recent communications and shared files, making the response more relevant.",source:{title:"Write effective prompts",url:"https://learn.microsoft.com/en-us/training/modules/employ-copilot-assistant/3-write-effective-prompts-optimize-copilot-responses",video:{title:"Episode 2: Copilot Chat as your AI assistant",url:"https://www.youtube.com/watch?v=Nc0jM8lh9II"}}},{id:137,skill:2,section:"2A",bullet:"reference-resources",topic:"Referencing Meetings with #",question:"You want Copilot to summarize action items from a recent project meeting. Which reference command should you use?",options:["/ followed by the meeting recording file name","# followed by the meeting name to reference the meeting transcript and details","@ followed by the meeting organizer's name","Type 'meeting summary' and Copilot will find it automatically"],correct:1,explanation:"The # command references meetings by name, giving Copilot access to the meeting transcript, notes, and details for summarization or action item extraction.",source:{title:"Write effective prompts",url:"https://learn.microsoft.com/en-us/training/modules/employ-copilot-assistant/3-write-effective-prompts-optimize-copilot-responses",video:{title:"Episode 2: Copilot Chat as your AI assistant",url:"https://www.youtube.com/watch?v=Nc0jM8lh9II"}}},{id:138,skill:2,section:"2A",bullet:"save-prompt",topic:"Saving Prompts",question:"You have crafted a detailed prompt for generating weekly status reports that you want to reuse every Friday. What should you do?",options:["Copy the prompt text into a Word document for safekeeping","Save the prompt in Copilot so you can reuse it directly without retyping","Memorize the prompt since Copilot doesn't support saving","Email the prompt to yourself each week"],correct:1,explanation:"Copilot allows you to save prompts for reuse. Saved prompts can be accessed quickly, ensuring consistency and saving time on recurring tasks.",source:{title:"Manage prompts and conversations",url:"https://learn.microsoft.com/en-us/training/modules/employ-copilot-assistant/4-manage-prompts-conversations-copilot-chat",video:{title:"Episode 2: Copilot Chat as your AI assistant",url:"https://www.youtube.com/watch?v=Nc0jM8lh9II"}}},{id:139,skill:2,section:"2A",bullet:"save-prompt",topic:"Saving Prompts",question:"Where can you find your saved prompts in Copilot Chat?",options:["In the Microsoft 365 admin center","In the Copilot prompt library accessible from the Copilot Chat interface","In your Outlook drafts folder","In a SharePoint document library created automatically"],correct:1,explanation:"Saved prompts are accessible from the Copilot Chat interface through the prompt library, making them easy to find and reuse.",source:{title:"Manage prompts and conversations",url:"https://learn.microsoft.com/en-us/training/modules/employ-copilot-assistant/4-manage-prompts-conversations-copilot-chat",video:{title:"Episode 2: Copilot Chat as your AI assistant",url:"https://www.youtube.com/watch?v=Nc0jM8lh9II"}}},{id:140,skill:2,section:"2A",bullet:"save-prompt",topic:"Saving Prompts",question:"What is a key benefit of saving a prompt versus retyping it each time?",options:["Saved prompts run faster than typed prompts","Saved prompts guarantee identical results every time","Saved prompts ensure consistency and save time, especially for recurring tasks","Saved prompts bypass the need for a Copilot license"],correct:2,explanation:"Saving prompts ensures you use the same well-crafted wording each time, maintaining consistency and eliminating the effort of reconstructing complex prompts from memory.",source:{title:"Manage prompts and conversations",url:"https://learn.microsoft.com/en-us/training/modules/employ-copilot-assistant/4-manage-prompts-conversations-copilot-chat",video:{title:"Episode 2: Copilot Chat as your AI assistant",url:"https://www.youtube.com/watch?v=Nc0jM8lh9II"}}},{id:141,skill:2,section:"2A",bullet:"schedule-prompt",topic:"Scheduling Prompts",question:"You want Copilot to automatically generate a project status summary every Monday morning. Which feature supports this?",options:["Setting a recurring calendar event with a Copilot link","Scheduling the prompt to run automatically at a specified time","Creating a Power Automate flow that calls Copilot","Asking a colleague to run the prompt on your behalf each Monday"],correct:1,explanation:"Copilot supports scheduling prompts to run at specified times, automating recurring tasks like weekly status summaries without manual intervention.",source:{title:"Manage prompts and conversations",url:"https://learn.microsoft.com/en-us/training/modules/employ-copilot-assistant/4-manage-prompts-conversations-copilot-chat",video:{title:"Episode 2: Copilot Chat as your AI assistant",url:"https://www.youtube.com/watch?v=Nc0jM8lh9II"}}},{id:142,skill:2,section:"2A",bullet:"schedule-prompt",topic:"Scheduling Prompts",question:"What is a prerequisite for scheduling a prompt in Copilot?",options:["The prompt must be shorter than 100 words","The prompt must first be saved before it can be scheduled","You must have admin rights to the Microsoft 365 tenant","Scheduled prompts only work in Web mode"],correct:1,explanation:"To schedule a prompt, you need to save it first. Once saved, you can configure it to run on a recurring schedule.",source:{title:"Manage prompts and conversations",url:"https://learn.microsoft.com/en-us/training/modules/employ-copilot-assistant/4-manage-prompts-conversations-copilot-chat",video:{title:"Episode 2: Copilot Chat as your AI assistant",url:"https://www.youtube.com/watch?v=Nc0jM8lh9II"}}},{id:143,skill:2,section:"2A",bullet:"schedule-prompt",topic:"Scheduling Prompts",question:"A team lead schedules a prompt to summarize team emails every Friday at 4 PM. Where will the results appear?",options:["In a new email sent to the team lead","In the Copilot Chat conversation history, ready for the team lead to review","In a shared SharePoint page automatically","In the Microsoft 365 admin activity log"],correct:1,explanation:"Scheduled prompt results appear in the user's Copilot Chat history, where they can review, edit, and share the output as needed.",source:{title:"Manage prompts and conversations",url:"https://learn.microsoft.com/en-us/training/modules/employ-copilot-assistant/4-manage-prompts-conversations-copilot-chat",video:{title:"Episode 2: Copilot Chat as your AI assistant",url:"https://www.youtube.com/watch?v=Nc0jM8lh9II"}}},{id:144,skill:2,section:"2A",bullet:"share-prompt",topic:"Sharing Prompts",question:"You created a highly effective prompt for drafting customer proposals. How can your teammates benefit from it?",options:["They cannot — prompts are always private","Share the prompt with them so they can use the same optimized wording","Email them a screenshot of the prompt","They must recreate it themselves based on your verbal description"],correct:1,explanation:"Copilot allows you to share saved prompts with colleagues, enabling teams to standardize on effective prompt patterns without everyone having to craft them independently.",source:{title:"Manage prompts and conversations",url:"https://learn.microsoft.com/en-us/training/modules/employ-copilot-assistant/4-manage-prompts-conversations-copilot-chat",video:{title:"Episode 2: Copilot Chat as your AI assistant",url:"https://www.youtube.com/watch?v=Nc0jM8lh9II"}}},{id:145,skill:2,section:"2A",bullet:"share-prompt",topic:"Sharing Prompts",question:"When you share a prompt with a colleague, what do they receive?",options:["A copy of your conversation history with Copilot","The prompt template that they can run with their own data and context","Full access to all files you referenced in the original prompt","An invitation to co-edit the prompt in real time"],correct:1,explanation:"Sharing a prompt gives colleagues the prompt template itself. When they run it, Copilot uses their own permissions and data context — not yours.",source:{title:"Manage prompts and conversations",url:"https://learn.microsoft.com/en-us/training/modules/employ-copilot-assistant/4-manage-prompts-conversations-copilot-chat",video:{title:"Episode 2: Copilot Chat as your AI assistant",url:"https://www.youtube.com/watch?v=Nc0jM8lh9II"}}},{id:146,skill:2,section:"2A",bullet:"share-prompt",topic:"Sharing Prompts",question:"A manager wants to ensure their entire team uses the same prompt structure for client briefings. What is the best approach?",options:["Print the prompt and distribute paper copies","Create and save the prompt, then share it with the team through Copilot's sharing feature","Have each team member write their own prompt and hope for consistency","Create a mandatory training course on prompt writing"],correct:1,explanation:"The most efficient approach is to create, save, and share the prompt through Copilot's built-in sharing feature, ensuring everyone uses the same optimized template.",source:{title:"Manage prompts and conversations",url:"https://learn.microsoft.com/en-us/training/modules/employ-copilot-assistant/4-manage-prompts-conversations-copilot-chat",video:{title:"Episode 2: Copilot Chat as your AI assistant",url:"https://www.youtube.com/watch?v=Nc0jM8lh9II"}}},{id:147,skill:2,section:"2B",bullet:"find-conversations",topic:"Finding Past Conversations",question:"You had a useful Copilot conversation last week about budget planning but cannot remember the exact prompt. How do you find it?",options:["Search your email inbox for a Copilot notification","Browse your recent conversations in the Copilot Chat history panel","Ask Copilot to recall all your previous conversations","Check the Microsoft 365 admin audit log"],correct:1,explanation:"Copilot Chat maintains a conversation history panel where you can browse and search previous conversations. This makes it easy to find and revisit past interactions.",source:{title:"Manage prompts and conversations",url:"https://learn.microsoft.com/en-us/training/modules/employ-copilot-assistant/4-manage-prompts-conversations-copilot-chat",video:{title:"Episode 2: Copilot Chat as your AI assistant",url:"https://www.youtube.com/watch?v=Nc0jM8lh9II"}}},{id:148,skill:2,section:"2B",bullet:"find-conversations",topic:"Temporary Chat",question:"You want to ask Copilot a sensitive question without it being saved in your conversation history. Which feature should you use?",options:["Web mode — it never saves conversations","Temporary chat — the conversation is not saved to your history","Incognito mode in your browser","There is no way to prevent conversations from being saved"],correct:1,explanation:"Temporary chat allows you to have a conversation that is not saved in your Copilot Chat history. This is useful for one-off or sensitive queries.",source:{title:"Manage prompts and conversations",url:"https://learn.microsoft.com/en-us/training/modules/employ-copilot-assistant/4-manage-prompts-conversations-copilot-chat",video:{title:"Episode 2: Copilot Chat as your AI assistant",url:"https://www.youtube.com/watch?v=Nc0jM8lh9II"}}},{id:149,skill:2,section:"2B",bullet:"find-conversations",topic:"Finding Past Conversations",question:"What is the easiest way to locate a specific past conversation about 'Q4 marketing plan' in Copilot Chat?",options:["Scroll through all conversations chronologically","Use the search function in the conversation history to find it by keyword","Ask Copilot in a new chat to find old conversations","Check your browser's download history"],correct:1,explanation:"The conversation history in Copilot Chat includes search functionality, allowing you to find past conversations by keyword rather than scrolling through them manually.",source:{title:"Manage prompts and conversations",url:"https://learn.microsoft.com/en-us/training/modules/employ-copilot-assistant/4-manage-prompts-conversations-copilot-chat",video:{title:"Episode 2: Copilot Chat as your AI assistant",url:"https://www.youtube.com/watch?v=Nc0jM8lh9II"}}},{id:150,skill:2,section:"2B",bullet:"delete-chat",topic:"Deleting a Chat",question:"You accidentally discussed a sensitive topic in a Copilot Chat conversation. What can you do?",options:["Nothing — all conversations are permanent","Delete the conversation from your Copilot Chat history","Ask your IT admin to purge the conversation from Microsoft servers","Edit the conversation to remove the sensitive parts"],correct:1,explanation:"Copilot Chat allows users to delete conversations from their history. This removes the conversation from your view and helps manage sensitive content.",source:{title:"Manage prompts and conversations",url:"https://learn.microsoft.com/en-us/training/modules/employ-copilot-assistant/4-manage-prompts-conversations-copilot-chat",video:{title:"Episode 2: Copilot Chat as your AI assistant",url:"https://www.youtube.com/watch?v=Nc0jM8lh9II"}}},{id:151,skill:2,section:"2B",bullet:"delete-chat",topic:"Deleting a Chat",question:"After deleting a Copilot Chat conversation, can you recover it?",options:["Yes, from the Recycle Bin within 30 days","Yes, by asking Copilot to restore it","No — deleted conversations cannot be recovered by the user","Yes, through the Microsoft 365 admin center"],correct:2,explanation:"Once a conversation is deleted from Copilot Chat, it cannot be recovered by the user. Users should be certain before deleting conversations.",source:{title:"Manage prompts and conversations",url:"https://learn.microsoft.com/en-us/training/modules/employ-copilot-assistant/4-manage-prompts-conversations-copilot-chat",video:{title:"Episode 2: Copilot Chat as your AI assistant",url:"https://www.youtube.com/watch?v=Nc0jM8lh9II"}}},{id:152,skill:2,section:"2B",bullet:"delete-chat",topic:"Temporary Chat vs Delete",question:"What is the difference between using Temporary Chat and deleting a conversation after the fact?",options:["There is no difference — both achieve the same result","Temporary Chat bypasses memory and personalization and is never saved; deleting removes an already-saved conversation from history","Temporary Chat is only available in Web mode","Deleting a chat also removes it from Copilot's memory; Temporary Chat does not"],correct:1,explanation:"Temporary Chat is proactive — it bypasses memory/personalization and the conversation is never saved. Deleting is reactive — it removes a conversation that was already saved to history.",source:{title:"Manage prompts and conversations",url:"https://learn.microsoft.com/en-us/training/modules/employ-copilot-assistant/4-manage-prompts-conversations-copilot-chat",video:{title:"Episode 2: Copilot Chat as your AI assistant",url:"https://www.youtube.com/watch?v=Nc0jM8lh9II"}}},{id:153,skill:2,section:"2B",bullet:"rename-chat",topic:"Renaming a Chat",question:"Copilot automatically names your conversations based on the first prompt. You started a chat about budget planning, but it evolved into a staffing discussion. What should you do?",options:["Start a new conversation with a better first prompt","Rename the conversation to reflect its actual content, like 'Q4 Staffing Discussion'","Nothing — conversation names cannot be changed","Add a bookmark to the conversation instead"],correct:1,explanation:"Copilot Chat allows you to rename conversations. Renaming helps you organize and find conversations later, especially when the topic evolved beyond the original prompt.",source:{title:"Manage prompts and conversations",url:"https://learn.microsoft.com/en-us/training/modules/employ-copilot-assistant/4-manage-prompts-conversations-copilot-chat",video:{title:"Episode 2: Copilot Chat as your AI assistant",url:"https://www.youtube.com/watch?v=Nc0jM8lh9II"}}},{id:154,skill:2,section:"2B",bullet:"rename-chat",topic:"Renaming a Chat",question:"What is the primary benefit of renaming Copilot Chat conversations?",options:["It improves the quality of Copilot's responses in that conversation","It makes conversations easier to find and organize in your history","It shares the conversation with your team automatically","It prevents the conversation from being deleted"],correct:1,explanation:"Renaming conversations makes them easier to locate in your history. A descriptive name helps you quickly identify the right conversation without opening each one.",source:{title:"Manage prompts and conversations",url:"https://learn.microsoft.com/en-us/training/modules/employ-copilot-assistant/4-manage-prompts-conversations-copilot-chat",video:{title:"Episode 2: Copilot Chat as your AI assistant",url:"https://www.youtube.com/watch?v=Nc0jM8lh9II"}}},{id:155,skill:2,section:"2B",bullet:"rename-chat",topic:"Renaming a Chat",question:"You have 20 Copilot conversations all auto-named with generic titles. Which approach helps you manage them effectively?",options:["Delete all of them and start fresh","Rename each one with a descriptive title that reflects the topic discussed","Export them all to a Word document","Ask Copilot to organize them into folders"],correct:1,explanation:"Renaming conversations with descriptive titles is the most practical way to organize a large conversation history, making each one identifiable at a glance.",source:{title:"Manage prompts and conversations",url:"https://learn.microsoft.com/en-us/training/modules/employ-copilot-assistant/4-manage-prompts-conversations-copilot-chat",video:{title:"Episode 2: Copilot Chat as your AI assistant",url:"https://www.youtube.com/watch?v=Nc0jM8lh9II"}}},{id:156,skill:2,section:"2B",bullet:"add-to-notebook",topic:"Adding to a Notebook",question:"During a Copilot conversation, you receive a thorough research analysis that you want to preserve for deep reference. What is the best action?",options:["Copy and paste the response into a Word document","Add the conversation to a Copilot Notebook for deep research and extended reference","Take a screenshot of the response","Print the conversation for your files"],correct:1,explanation:"Copilot Notebooks are designed for deep research and extended reference. Adding a conversation to a notebook preserves the content in a format optimized for thorough exploration.",source:{title:"Manage prompts and conversations",url:"https://learn.microsoft.com/en-us/training/modules/employ-copilot-assistant/4-manage-prompts-conversations-copilot-chat",video:{title:"Episode 2: Copilot Chat as your AI assistant",url:"https://www.youtube.com/watch?v=Nc0jM8lh9II"}}},{id:157,skill:2,section:"2B",bullet:"add-to-notebook",topic:"Notebooks vs Pages",question:"What is the key difference between a Copilot Notebook and a Copilot Page?",options:["Notebooks are for sharing; Pages are for personal use","Notebooks are for deep, individual research; Pages are for real-time team collaboration","Notebooks are stored in OneDrive; Pages are stored in SharePoint","There is no difference — they are the same feature with different names"],correct:1,explanation:"Copilot Notebooks are designed for deep individual research and can handle longer, more complex prompts. Copilot Pages are collaborative spaces where teams can work together in real time.",source:{title:"Enhance collaboration with chat, pages, and notebooks",url:"https://learn.microsoft.com/en-us/training/modules/manage-meetings-collaboration/3-enhance-collaboration-chat-pages-notebooks",video:{title:"Episode 5: Manage meetings and collaboration",url:"https://www.youtube.com/watch?v=9fMVHrON8cs"}}},{id:158,skill:2,section:"2B",bullet:"add-to-notebook",topic:"Notebook Limitations",question:"Can Copilot Notebooks be exported to Word documents?",options:["Yes — you can export a Notebook directly to Word","No — Notebooks cannot be converted to Word, but Copilot Pages can","Only if you copy and paste the content manually","Only if you have a Copilot Studio license"],correct:1,explanation:"Notebooks cannot be exported to Word. However, Copilot Pages support export to Word documents. This is a key distinction between the two features.",source:{title:"Enhance collaboration with chat, pages, and notebooks",url:"https://learn.microsoft.com/en-us/training/modules/manage-meetings-collaboration/3-enhance-collaboration-chat-pages-notebooks",video:{title:"Episode 5: Manage meetings and collaboration",url:"https://www.youtube.com/watch?v=9fMVHrON8cs"}}},{id:159,skill:2,section:"2C",bullet:"agent-store-vs-create",topic:"Agent Store vs Custom Agent",question:"Your team needs an agent that can answer questions about company-specific HR policies. Should you use the Agent Store or create a custom agent?",options:["Use the Agent Store — it has an HR agent ready to use","Create a custom agent because company-specific HR policies require custom knowledge sources","Neither — use Copilot Chat with Work mode instead","Use the Agent Store and modify its responses manually"],correct:1,explanation:"The Agent Store contains pre-built agents for common tasks. For company-specific knowledge like internal HR policies, you should create a custom agent with your own knowledge sources.",source:{title:"Copilot agents defined",url:"https://learn.microsoft.com/en-us/training/modules/employ-copilot-assistant/4a-copilot-agents-defined",video:{title:"Episode 2: Copilot Chat as your AI assistant",url:"https://www.youtube.com/watch?v=Nc0jM8lh9II"}}},{id:160,skill:2,section:"2C",bullet:"agent-store-vs-create",topic:"Agent Store vs Custom Agent",question:"When should you choose an agent from the Agent Store instead of building your own?",options:["When you need the agent to access confidential internal documents","When a pre-built agent already meets your needs for a common task without requiring custom knowledge","When you want full control over the agent's instructions and behavior","When you need the agent to work with only your team's SharePoint site"],correct:1,explanation:"The Agent Store is ideal when a pre-built agent already handles your use case (e.g., general research, writing assistance). Custom agents are needed when you require specific organizational knowledge or tailored behavior.",source:{title:"Copilot agents defined",url:"https://learn.microsoft.com/en-us/training/modules/employ-copilot-assistant/4a-copilot-agents-defined",video:{title:"Episode 2: Copilot Chat as your AI assistant",url:"https://www.youtube.com/watch?v=Nc0jM8lh9II"}}},{id:161,skill:2,section:"2C",bullet:"agent-store-vs-create",topic:"Researcher Agent",question:"Which is an example of a pre-built agent you might find in the Agent Store?",options:["An agent trained on your company's internal product documentation","The Researcher agent that performs deep web research and generates structured reports","An agent that answers questions about your team's sprint backlog","An agent customized with your department's writing style guide"],correct:1,explanation:"The Researcher agent is a pre-built agent available in the Agent Store. It performs deep web research and creates structured reports — a general capability that does not require custom knowledge.",source:{title:"Research and gather with the Researcher agent",url:"https://learn.microsoft.com/en-us/training/modules/draft-refine-business-content/3-research-gather-researcher-agent",video:{title:"Episode 3: Draft and refine business content",url:"https://www.youtube.com/watch?v=O9Fx8lVdYtc"}}},{id:162,skill:2,section:"2C",bullet:"create-agent-template",topic:"Creating Agent from Template",question:"You want to create a custom agent quickly without starting from scratch. What is the fastest approach?",options:["Write the agent code in Visual Studio","Start from a template in the Copilot agent builder and customize it for your needs","Clone an agent from the Agent Store and modify its source code","Submit a request to Microsoft to build one for you"],correct:1,explanation:"The Copilot agent builder offers templates as starting points. You can select a template that matches your scenario and customize the instructions, knowledge, and settings.",source:{title:"Copilot agents defined",url:"https://learn.microsoft.com/en-us/training/modules/employ-copilot-assistant/4a-copilot-agents-defined",video:{title:"Episode 2: Copilot Chat as your AI assistant",url:"https://www.youtube.com/watch?v=Nc0jM8lh9II"}}},{id:163,skill:2,section:"2C",bullet:"create-agent-template",topic:"Creating Agent from Template",question:"What does a template provide when you create a new Copilot agent?",options:["Only the agent's name and icon","A pre-configured starting point with sample instructions, suggested prompts, and a framework you can customize","A fully finished agent that cannot be modified","An empty shell with no configuration at all"],correct:1,explanation:"Templates provide a pre-configured foundation including sample instructions, suggested prompts, and structure. You then customize these elements to match your specific use case.",source:{title:"Copilot agents defined",url:"https://learn.microsoft.com/en-us/training/modules/employ-copilot-assistant/4a-copilot-agents-defined",video:{title:"Episode 2: Copilot Chat as your AI assistant",url:"https://www.youtube.com/watch?v=Nc0jM8lh9II"}}},{id:164,skill:2,section:"2C",bullet:"create-agent-template",topic:"No-Code Agent Creation",question:"Do you need programming skills to create a basic Copilot agent?",options:["Yes — Python is required","Yes — C# is required","No — you can use templates and natural language descriptions in the no-code builder","Yes — SQL is required for knowledge source queries"],correct:2,explanation:"Basic Copilot agents can be created without any code using templates, natural language descriptions, and the visual builder. No programming skills are needed.",source:{title:"Copilot agents defined",url:"https://learn.microsoft.com/en-us/training/modules/employ-copilot-assistant/4a-copilot-agents-defined",video:{title:"Episode 2: Copilot Chat as your AI assistant",url:"https://www.youtube.com/watch?v=Nc0jM8lh9II"}}},{id:165,skill:2,section:"2C",bullet:"configure-agent-knowledge",topic:"Agent Knowledge Sources",question:"You are building an agent to help sales reps find product specifications. Which knowledge source should you add?",options:["The company's public website","The SharePoint document library containing product specification sheets","A personal OneDrive folder with draft notes","The Microsoft Learn documentation site"],correct:1,explanation:"The agent should be grounded in the authoritative source of product specifications — the SharePoint library where they are maintained. This ensures accurate, up-to-date responses.",source:{title:"Copilot agents defined",url:"https://learn.microsoft.com/en-us/training/modules/employ-copilot-assistant/4a-copilot-agents-defined",video:{title:"Episode 2: Copilot Chat as your AI assistant",url:"https://www.youtube.com/watch?v=Nc0jM8lh9II"}}},{id:166,skill:2,section:"2C",bullet:"configure-agent-knowledge",topic:"Agent Knowledge Limits",question:"You attempt to add a 21st knowledge source to your Copilot agent. What happens?",options:["The source is added but with reduced priority","The agent builder prevents you from adding it because the maximum is 20 knowledge sources","The oldest knowledge source is automatically removed","The agent switches to a premium tier to accommodate more sources"],correct:1,explanation:"Copilot agents support a maximum of 20 knowledge sources. If you need to add another, you must remove an existing one first.",source:{title:"Copilot agents defined",url:"https://learn.microsoft.com/en-us/training/modules/employ-copilot-assistant/4a-copilot-agents-defined",video:{title:"Episode 2: Copilot Chat as your AI assistant",url:"https://www.youtube.com/watch?v=Nc0jM8lh9II"}}},{id:167,skill:2,section:"2C",bullet:"configure-agent-knowledge",topic:"Agent Knowledge Source Types",question:"What types of content can serve as knowledge sources for a Copilot agent?",options:["Only Word documents","SharePoint sites, uploaded files (PDF, Word, Excel), and external websites — up to 20 sources","Only publicly available websites","Only content stored in the agent creator's personal OneDrive"],correct:1,explanation:"Agent knowledge sources can include SharePoint sites, uploaded files of various types, and external websites, providing rich and varied context up to the 20-source maximum.",source:{title:"Copilot agents defined",url:"https://learn.microsoft.com/en-us/training/modules/employ-copilot-assistant/4a-copilot-agents-defined",video:{title:"Episode 2: Copilot Chat as your AI assistant",url:"https://www.youtube.com/watch?v=Nc0jM8lh9II"}}},{id:168,skill:2,section:"2C",bullet:"configure-agent-settings",topic:"Agent Instructions",question:"You are configuring a customer-support agent and want it to always respond in a professional, empathetic tone and never discuss competitor products. Where do you specify this?",options:["In the agent's knowledge sources","In the agent's instructions field, which defines behavior, tone, and boundaries","In a separate policy document linked to the agent","In the agent's name and description"],correct:1,explanation:"The instructions field is where you define the agent's behavioral rules, tone, and boundaries — such as maintaining a professional tone and avoiding competitor discussions.",source:{title:"Copilot agents defined",url:"https://learn.microsoft.com/en-us/training/modules/employ-copilot-assistant/4a-copilot-agents-defined",video:{title:"Episode 2: Copilot Chat as your AI assistant",url:"https://www.youtube.com/watch?v=Nc0jM8lh9II"}}},{id:169,skill:2,section:"2C",bullet:"configure-agent-settings",topic:"Agent Suggested Prompts",question:"What is the purpose of adding suggested prompts to a Copilot agent?",options:["They restrict what users can ask the agent","They provide starter examples that help users understand what the agent can do and how to interact with it","They automatically run when the agent is first opened","They replace the need for instructions"],correct:1,explanation:"Suggested prompts appear as clickable examples when users open the agent. They help users quickly understand the agent's capabilities and provide a starting point for interaction.",source:{title:"Copilot agents defined",url:"https://learn.microsoft.com/en-us/training/modules/employ-copilot-assistant/4a-copilot-agents-defined",video:{title:"Episode 2: Copilot Chat as your AI assistant",url:"https://www.youtube.com/watch?v=Nc0jM8lh9II"}}},{id:170,skill:2,section:"2C",bullet:"configure-agent-settings",topic:"Agent Capabilities",question:"When configuring an agent's capabilities, which of the following can you enable?",options:["Access to external databases outside Microsoft 365","The ability to generate images, interpret code, or search the web depending on the agent's purpose","Direct access to the user's local hard drive","The ability to send emails on behalf of the user without confirmation"],correct:1,explanation:"Agent capabilities include options like image generation, code interpretation, and web search. These are toggled on or off based on what the agent needs to accomplish its task.",source:{title:"Copilot agents defined",url:"https://learn.microsoft.com/en-us/training/modules/employ-copilot-assistant/4a-copilot-agents-defined",video:{title:"Episode 2: Copilot Chat as your AI assistant",url:"https://www.youtube.com/watch?v=Nc0jM8lh9II"}}},{id:171,skill:2,section:"2C",bullet:"share-agent",topic:"Sharing an Agent",question:"You built a helpful Copilot agent for your team. How do you make it available to your colleagues?",options:["Export the agent as a file and email it to each person","Share the agent with specific people, a Microsoft 365 group, or your entire organization","Ask each colleague to recreate the agent using the same settings","Publish it to the public Microsoft App Store"],correct:1,explanation:"Copilot agents can be shared with specific people, Microsoft 365 groups, or the entire organization, making them accessible to the intended audience.",source:{title:"Copilot agents defined",url:"https://learn.microsoft.com/en-us/training/modules/employ-copilot-assistant/4a-copilot-agents-defined",video:{title:"Episode 2: Copilot Chat as your AI assistant",url:"https://www.youtube.com/watch?v=Nc0jM8lh9II"}}},{id:172,skill:2,section:"2C",bullet:"share-agent",topic:"Sharing an Agent",question:"When a shared agent references knowledge sources in SharePoint, what determines whether a user can access the information through the agent?",options:["The agent creator's permissions — all users of the agent see the same data","Each user's own Microsoft 365 permissions — the agent respects individual access rights","The agent's sharing settings override SharePoint permissions","All shared agents provide read-only access to all knowledge sources"],correct:1,explanation:"Even when using a shared agent, each user's responses are filtered through their own Microsoft 365 permissions. If a user lacks access to a knowledge source, the agent will not surface that content.",source:{title:"Copilot agents defined",url:"https://learn.microsoft.com/en-us/training/modules/employ-copilot-assistant/4a-copilot-agents-defined",video:{title:"Episode 2: Copilot Chat as your AI assistant",url:"https://www.youtube.com/watch?v=Nc0jM8lh9II"}}},{id:173,skill:2,section:"2C",bullet:"share-agent",topic:"Sharing an Agent",question:"After you share an agent with your team, can you later revoke their access?",options:["No — once shared, access is permanent","Yes — you can manage and revoke access at any time","Only if you delete the agent entirely","Only the IT administrator can revoke access"],correct:1,explanation:"You maintain control over agent access. You can add or revoke access for users and groups at any time, just like managing permissions for any shared resource.",source:{title:"Copilot agents defined",url:"https://learn.microsoft.com/en-us/training/modules/employ-copilot-assistant/4a-copilot-agents-defined",video:{title:"Episode 2: Copilot Chat as your AI assistant",url:"https://www.youtube.com/watch?v=Nc0jM8lh9II"}}},{id:174,skill:3,section:"3A",bullet:"create-doc-from-prompt",topic:"Creating Documents from Prompts",question:"You need to create a project charter document. Which approach uses Copilot in Word most effectively?",options:["Open a blank document and type the charter manually, then ask Copilot to fix grammar","Open Word, use Copilot's 'Draft with Copilot' feature, and provide a detailed prompt specifying the project name, objectives, stakeholders, and desired format","Ask Copilot Chat to create the charter, then copy-paste into Word","Use a Word template and ignore Copilot"],correct:1,explanation:"The 'Draft with Copilot' feature in Word lets you generate a full document directly from a detailed prompt. Including specifics like objectives and format produces a more complete first draft.",source:{title:"Draft content using Copilot",url:"https://learn.microsoft.com/en-us/training/modules/draft-refine-business-content/2-draft-content-using-copilot",video:{title:"Episode 3: Draft and refine business content",url:"https://www.youtube.com/watch?v=O9Fx8lVdYtc"}}},{id:175,skill:3,section:"3A",bullet:"create-doc-from-prompt",topic:"Creating Documents from Prompts",question:"When using Copilot to draft a new document in Word, which prompt component helps ensure the output matches your company's style?",options:["Goal — telling Copilot what type of document to create","Source — referencing a file to include data from","Expectations — specifying tone, format, length, and style requirements","Context — describing the business situation"],correct:2,explanation:"Expectations define the format, tone, length, and style you want. For example, 'Use a professional tone, include headers for each section, and keep it under 2 pages' guides Copilot's output.",source:{title:"Write effective prompts",url:"https://learn.microsoft.com/en-us/training/modules/employ-copilot-assistant/3-write-effective-prompts-optimize-copilot-responses",video:{title:"Episode 2: Copilot Chat as your AI assistant",url:"https://www.youtube.com/watch?v=Nc0jM8lh9II"}}},{id:176,skill:3,section:"3A",bullet:"create-doc-from-prompt",topic:"Copilot in Outlook Limitations",question:"Can Copilot in Outlook schedule emails to send at a later time?",options:["Yes — it can schedule any email","No — Copilot can draft, summarize, and adjust tone but cannot schedule emails to send later","Only on the desktop app, not Outlook web","Only for recurring emails"],correct:1,explanation:"Copilot in Outlook can draft, reply, summarize, and adjust tone — but it cannot schedule emails to send at a later time. This is a known content-vs-property limitation.",source:{title:"Draft content using Copilot",url:"https://learn.microsoft.com/en-us/training/modules/draft-refine-business-content/2-draft-content-using-copilot",video:{title:"Episode 3: Draft and refine business content",url:"https://www.youtube.com/watch?v=O9Fx8lVdYtc"}}},{id:177,skill:3,section:"3A",bullet:"generate-from-existing",topic:"Generating from Existing Documents",question:"You have a detailed technical specification in Word and need to create a PowerPoint presentation for stakeholders. How does Copilot help?",options:["You must manually copy content from Word to PowerPoint slide by slide","Use Copilot in PowerPoint and reference the Word document with / to generate a presentation based on its content","Copilot in Word can export directly to PowerPoint format","You need to save the Word document as a PDF first"],correct:1,explanation:"Copilot in PowerPoint can reference an existing Word document using the / command and generate a full presentation based on its content, saving significant manual effort.",source:{title:"Draft content using Copilot",url:"https://learn.microsoft.com/en-us/training/modules/draft-refine-business-content/2-draft-content-using-copilot",video:{title:"Episode 3: Draft and refine business content",url:"https://www.youtube.com/watch?v=O9Fx8lVdYtc"}}},{id:178,skill:3,section:"3A",bullet:"generate-from-existing",topic:"Generating from Existing Documents",question:"You need to transform a lengthy annual report into a concise 1-page executive brief. Which Copilot approach is best?",options:["Ask Copilot Chat to summarize the report from memory","Open Word, use Copilot to draft a new document, reference the annual report with /, and specify 'Create a 1-page executive brief highlighting key metrics and strategic priorities'","Manually delete sections from the annual report until it fits on one page","Use Copilot in Excel to extract the key data"],correct:1,explanation:"Referencing the existing document and providing specific expectations (1-page, key metrics, strategic priorities) guides Copilot to produce a well-structured executive brief.",source:{title:"Draft content using Copilot",url:"https://learn.microsoft.com/en-us/training/modules/draft-refine-business-content/2-draft-content-using-copilot",video:{title:"Episode 3: Draft and refine business content",url:"https://www.youtube.com/watch?v=O9Fx8lVdYtc"}}},{id:179,skill:3,section:"3A",bullet:"generate-from-existing",topic:"Excel Chat Mode vs App Skill Mode",question:"In Copilot for Excel, what is the difference between Chat mode and App Skill mode?",options:["They are the same thing","Chat mode is for asking questions and analyzing data conversationally; App Skill mode is for executing actions like creating formulas, charts, and columns","Chat mode is for web data; App Skill mode is for work data","Chat mode is faster; App Skill mode is more accurate"],correct:1,explanation:"Chat mode lets you ask questions and get insights conversationally. App Skill mode executes actions — creating formula columns, generating charts, inserting new sheets, and more.",source:{title:"Analyze data workflows in Excel",url:"https://learn.microsoft.com/en-us/training/modules/analyze-visualize-data-copilot/2-analyze-data-workflows-excel",video:{title:"Episode 4: Analyze and visualize data",url:"https://www.youtube.com/watch?v=l8gj-ICwQRs"}}},{id:180,skill:3,section:"3A",bullet:"management-summary",topic:"Management Summary",question:"Your director asks for a management summary of a 50-page project report before a board meeting. How do you use Copilot most effectively?",options:["Ask Copilot Chat to 'summarize project reports' without referencing any specific file","Open the report in Word and ask Copilot to 'Generate a management summary highlighting status, risks, budget, and next steps in bullet format'","Manually read the report and write the summary yourself","Use Copilot in Excel to analyze the report"],correct:1,explanation:"Opening the document in Word and using Copilot with a specific prompt ensures the summary is grounded in the actual report content and formatted for management consumption.",source:{title:"Prepare a weekly status report",url:"https://learn.microsoft.com/en-us/training/modules/define-copilot-role-business-workflow/2-prepare-weekly-status-report",video:{title:"Episode 6: Define Copilot role in your workflow",url:"https://www.youtube.com/watch?v=ULBebaSF7Bw"}}},{id:181,skill:3,section:"3A",bullet:"management-summary",topic:"Researcher vs Analyst Agent",question:"You need to compare your company's product features against three competitor websites. Which agent should you use?",options:["Analyst — for data comparison","Researcher — it gathers and synthesizes information from documents and web sources","Copilot in Excel","Copilot in Word"],correct:1,explanation:"The Researcher agent gathers and synthesizes information from documents and web sources. Comparing products across competitor websites is research work, not structured data analysis.",source:{title:"Research and gather with the Researcher agent",url:"https://learn.microsoft.com/en-us/training/modules/draft-refine-business-content/3-research-gather-researcher-agent",video:{title:"Episode 3: Draft and refine business content",url:"https://www.youtube.com/watch?v=O9Fx8lVdYtc"}}},{id:182,skill:3,section:"3A",bullet:"management-summary",topic:"Analyst Agent",question:"You have an Excel spreadsheet with 12 months of expense data and need to find spending trends and create visualizations. Which agent is best suited?",options:["Researcher","Analyst — it specializes in structured data analysis, trend identification, and visualization in Excel","Copilot Chat in Work mode","Copilot in Word"],correct:1,explanation:"The Analyst agent specializes in structured data analysis in Excel — trend identification, chart creation, and complex calculations using a code interpreter. Researcher is for document/web research.",source:{title:"Generate insights using the Analyst agent",url:"https://learn.microsoft.com/en-us/training/modules/analyze-visualize-data-copilot/3-generate-insights-analyst-agent",video:{title:"Episode 4: Analyze and visualize data",url:"https://www.youtube.com/watch?v=l8gj-ICwQRs"}}},{id:183,skill:3,section:"3A",bullet:"management-summary",topic:"Verifying Management Summaries",question:"Copilot generates a management summary that includes a revenue figure you did not see in the source document. What should you do?",options:["Include it in the summary — Copilot must have found it in another file","Remove or verify the figure against the source document, as this may be a fabrication","Change the figure to a round number to make it look more plausible","Ask Copilot to confirm the number is correct"],correct:1,explanation:"Unverified figures may be fabrications. Always cross-reference Copilot's output against source documents, especially for quantitative claims in management summaries.",source:{title:"Understand responsible AI",url:"https://learn.microsoft.com/en-us/training/modules/what-generative-ai/3-understand-responsible-ai",video:{title:"Episode 1: What is generative AI?",url:"https://www.youtube.com/watch?v=bIqV5jilJKk"}}},{id:184,skill:3,section:"3A",bullet:"move-data-between-apps",topic:"Moving Data Between Apps",question:"You analyzed sales data in Excel with Copilot and now need to include the key insights in a PowerPoint presentation. What is the most efficient workflow?",options:["Manually retype the insights into PowerPoint slides","Use Copilot in PowerPoint and reference the Excel file to generate slides with the data insights","Export Excel as a PDF and attach it to a PowerPoint slide","Take screenshots of the Excel charts and paste them into PowerPoint"],correct:1,explanation:"Copilot enables cross-app workflows. You can reference an Excel file in PowerPoint using / and have Copilot generate slides that incorporate the data insights.",source:{title:"Draft content using Copilot",url:"https://learn.microsoft.com/en-us/training/modules/draft-refine-business-content/2-draft-content-using-copilot",video:{title:"Episode 3: Draft and refine business content",url:"https://www.youtube.com/watch?v=O9Fx8lVdYtc"}}},{id:185,skill:3,section:"3A",bullet:"move-data-between-apps",topic:"Chat to Page Workflow",question:"During a Copilot Chat conversation, you generate a useful analysis. You want to share it with your team for collaborative editing. What is the best next step?",options:["Copy the text and paste it into an email to the team","Send the response to a Copilot Page where the team can collaborate on it in real time","Ask each team member to run the same prompt individually","Print the conversation and distribute copies"],correct:1,explanation:"Copilot Pages allow you to move content from a chat conversation into a collaborative workspace where your team can view, edit, and build on the content together in real time.",source:{title:"Enhance collaboration with chat, pages, and notebooks",url:"https://learn.microsoft.com/en-us/training/modules/manage-meetings-collaboration/3-enhance-collaboration-chat-pages-notebooks",video:{title:"Episode 5: Manage meetings and collaboration",url:"https://www.youtube.com/watch?v=9fMVHrON8cs"}}},{id:186,skill:3,section:"3A",bullet:"move-data-between-apps",topic:"Cross-App Copilot Workflow",question:"What makes Copilot Chat unique compared to Copilot embedded in individual apps like Word or Excel?",options:["It is faster because it uses a different AI model","It acts as a cross-app command center — synthesizing data from Word, Excel, Teams, Outlook, and more from a single conversation","It has a different AI model than in-app Copilot","It does not require a Microsoft 365 license"],correct:1,explanation:"Copilot Chat connects across all M365 apps from one interface. Unlike app-specific Copilot (which works within one app), Chat synthesizes information across your entire work environment.",source:{title:"What is Copilot Chat?",url:"https://learn.microsoft.com/en-us/training/modules/employ-copilot-assistant/2-what-is-copilot-chat",video:{title:"Episode 2: Copilot Chat as your AI assistant",url:"https://www.youtube.com/watch?v=Nc0jM8lh9II"}}},{id:187,skill:3,section:"3B",bullet:"copilot-for-meetings",topic:"Copilot in Meetings — Prerequisites",question:"What must be enabled BEFORE a Teams meeting starts for Copilot to provide real-time summaries and action items?",options:["Screen sharing","Meeting transcription and/or recording must be enabled in the meeting properties","A minimum of 5 participants must join","The meeting chat must be turned on"],correct:1,explanation:"Copilot needs transcription and/or recording enabled BEFORE the meeting starts. Without them, Copilot is limited to the meeting chat only — no real-time summaries or action items from the discussion.",source:{title:"Streamline meeting preparation",url:"https://learn.microsoft.com/en-us/training/modules/manage-meetings-collaboration/2-streamline-meeting-prep",video:{title:"Episode 5: Manage meetings and collaboration",url:"https://www.youtube.com/watch?v=9fMVHrON8cs"}}},{id:188,skill:3,section:"3B",bullet:"copilot-for-meetings",topic:"Copilot in Meetings — Catching Up",question:"You join a Teams meeting 15 minutes late. How can Copilot help you catch up?",options:["It replays the audio from the beginning at 2x speed","It provides a real-time summary of what has been discussed so far, including key points and decisions","It sends you the meeting slides via email","It pauses the meeting until you have reviewed the agenda"],correct:1,explanation:"Copilot in Teams meetings can summarize the discussion so far, letting latecomers catch up on key points, decisions, and action items without interrupting the meeting.",source:{title:"Streamline meeting preparation",url:"https://learn.microsoft.com/en-us/training/modules/manage-meetings-collaboration/2-streamline-meeting-prep",video:{title:"Episode 5: Manage meetings and collaboration",url:"https://www.youtube.com/watch?v=9fMVHrON8cs"}}},{id:189,skill:3,section:"3B",bullet:"copilot-for-meetings",topic:"Copilot Meeting Recap",question:"After a Teams meeting ends, where can you find the Copilot-generated meeting recap?",options:["In your email inbox","In the meeting chat under the Recap tab, then select Copilot","In a separate Copilot app","In your calendar event description"],correct:1,explanation:"Open the meeting chat in Teams, go to the Recap tab, and select Copilot to view the AI-generated summary, key decisions, and action items.",source:{title:"Streamline meeting preparation",url:"https://learn.microsoft.com/en-us/training/modules/manage-meetings-collaboration/2-streamline-meeting-prep",video:{title:"Episode 5: Manage meetings and collaboration",url:"https://www.youtube.com/watch?v=9fMVHrON8cs"}}},{id:190,skill:3,section:"3B",bullet:"copilot-pages",topic:"Copilot Pages",question:"What is the primary purpose of Copilot Pages?",options:["To store personal notes that only you can see","To provide a collaborative canvas where team members can work together on AI-generated content in real time","To replace SharePoint as the organization's document management system","To create web pages for the company's public website"],correct:1,explanation:"Copilot Pages is a real-time collaborative space where multiple team members can view, edit, and build on AI-generated content together — turning individual Copilot output into team deliverables.",source:{title:"Enhance collaboration with chat, pages, and notebooks",url:"https://learn.microsoft.com/en-us/training/modules/manage-meetings-collaboration/3-enhance-collaboration-chat-pages-notebooks",video:{title:"Episode 5: Manage meetings and collaboration",url:"https://www.youtube.com/watch?v=9fMVHrON8cs"}}},{id:191,skill:3,section:"3B",bullet:"copilot-pages",topic:"Pages vs Notebooks",question:"Which feature distinguishes Copilot Pages from Copilot Notebooks?",options:["Pages support deep individual research with longer prompts","Pages support real-time multi-user collaboration and can be exported to Word documents","Pages are only accessible to the creator","Pages are stored locally on your device"],correct:1,explanation:"Pages support real-time multi-user collaboration and can be exported to Word. Notebooks are for individual deep research and cannot be converted to Word documents.",source:{title:"Enhance collaboration with chat, pages, and notebooks",url:"https://learn.microsoft.com/en-us/training/modules/manage-meetings-collaboration/3-enhance-collaboration-chat-pages-notebooks",video:{title:"Episode 5: Manage meetings and collaboration",url:"https://www.youtube.com/watch?v=9fMVHrON8cs"}}},{id:192,skill:3,section:"3B",bullet:"copilot-pages",topic:"Copilot Pages Workflow",question:"You receive a useful Copilot response in chat and want to collaborate on it with three teammates. What is the recommended workflow?",options:["Copy the response and paste it into a Teams group chat","Send the response to a Copilot Page and invite your teammates to collaborate in real time","Forward the response via email and ask each person to reply with edits","Share your entire Copilot Chat history with the team"],correct:1,explanation:"Sending a response to a Copilot Page creates a shared workspace where all team members can see, edit, and iterate on the content together in real time — the core purpose of Pages.",source:{title:"Enhance collaboration with chat, pages, and notebooks",url:"https://learn.microsoft.com/en-us/training/modules/manage-meetings-collaboration/3-enhance-collaboration-chat-pages-notebooks",video:{title:"Episode 5: Manage meetings and collaboration",url:"https://www.youtube.com/watch?v=9fMVHrON8cs"}}},{id:193,skill:3,section:"3B",bullet:"copilot-memory",topic:"Copilot Memory",question:"What is Copilot Memory?",options:["The amount of RAM allocated to Copilot on your device","A feature that allows Copilot to remember your preferences and past instructions across conversations","The storage space used by Copilot conversation logs in SharePoint","A tool for memorizing study materials for exams"],correct:1,explanation:"Copilot Memory allows the AI to remember your preferences, writing style, and key instructions across sessions, making it more personalized and efficient over time.",source:{title:"Enhance collaboration with chat, pages, and notebooks",url:"https://learn.microsoft.com/en-us/training/modules/manage-meetings-collaboration/3-enhance-collaboration-chat-pages-notebooks",video:{title:"Episode 5: Manage meetings and collaboration",url:"https://www.youtube.com/watch?v=9fMVHrON8cs"}}},{id:194,skill:3,section:"3B",bullet:"copilot-memory",topic:"Copilot Memory Preferences",question:"You tell Copilot: 'Remember that I always want summaries in bullet-point format.' In future conversations, what happens?",options:["Nothing — Copilot cannot retain preferences between conversations","Copilot remembers this preference and applies bullet-point formatting to summaries in future sessions","The preference is saved but only applies within the current conversation","Copilot saves the preference but requires you to activate it manually each time"],correct:1,explanation:"With Copilot Memory enabled, the AI retains preferences like formatting styles across conversations, automatically applying them without needing to be reminded each time.",source:{title:"Enhance collaboration with chat, pages, and notebooks",url:"https://learn.microsoft.com/en-us/training/modules/manage-meetings-collaboration/3-enhance-collaboration-chat-pages-notebooks",video:{title:"Episode 5: Manage meetings and collaboration",url:"https://www.youtube.com/watch?v=9fMVHrON8cs"}}},{id:195,skill:3,section:"3B",bullet:"copilot-memory",topic:"Managing Copilot Memory",question:"How can you manage what Copilot remembers about you?",options:["You cannot — memory is fully controlled by Microsoft","You can view and delete specific memories through Copilot's personalization settings","You must contact your IT administrator to manage memory","Memory resets automatically every 30 days"],correct:1,explanation:"Users have control over Copilot Memory. You can view what Copilot remembers, delete specific memories, or turn off the memory feature entirely through personalization settings.",source:{title:"Enhance collaboration with chat, pages, and notebooks",url:"https://learn.microsoft.com/en-us/training/modules/manage-meetings-collaboration/3-enhance-collaboration-chat-pages-notebooks",video:{title:"Episode 5: Manage meetings and collaboration",url:"https://www.youtube.com/watch?v=9fMVHrON8cs"}}}];